//! Replays vectors/conformance.json (generated by tests/gen_conformance.py from the Python reference)
//! and demands exact agreement on supply, every balance, every event and attestation, and the cap buckets after every step.
use serde_json::{json, Value};
use tremor::engine::*;

fn strs(v: &Value) -> Vec<String> { v.as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect() }

fn params(p: &Value, publishers: &Value, relief: &Value) -> Params {
    let g = |k: &str| p[k].as_u64().unwrap();
    Params { s0: g("s0") as u128, min_mag_x10: g("min_mag_x10") as u32, base_ppm: g("base_ppm") as u128, max_event_ppm: g("max_event_ppm") as u128,
        cooldown_s: g("cooldown_s"), week_cap_ppm: g("week_cap_ppm") as u128, month_cap_ppm: g("month_cap_ppm") as u128, min_age_s: g("min_age_s"),
        max_age_s: g("max_age_s"), max_open: g("max_open") as u32, max_claims: g("max_claims") as u32, claim_wait_s: g("claim_wait_s"),
        threshold: g("threshold") as u32, tap_amount: g("tap_amount") as u128, publishers: strs(publishers), relief: strs(relief) }
}

fn snapshot(c: &Core) -> Value {
    let tok: serde_json::Map<String, Value> = c.tok.iter().filter(|(_, v)| **v != 0).map(|(k, v)| (k.clone(), json!(*v as u64))).collect();
    let buckets: serde_json::Map<String, Value> = c.buckets.iter().filter(|(_, v)| **v != 0).map(|(k, v)| (k.to_string(), json!(*v as u64))).collect();
    let events: serde_json::Map<String, Value> = c.ev.iter().map(|(k, e)| {
        let versions: Vec<Value> = e.versions.iter().map(|((m, o), s)| json!([*m, *o, s.iter().collect::<Vec<_>>()])).collect();
        (k.clone(), json!([e.status.as_str(), e.minted as u64, e.clipped, e.claimer.clone().unwrap_or_default(), e.created_at, versions]))
    }).collect();
    json!({"supply": c.supply as u64, "tok": tok, "buckets": buckets, "recent": c.recent, "tapped": c.tapped.iter().collect::<Vec<_>>(), "events": events})
}

#[test]
fn rust_matches_python_reference() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../vectors/conformance.json");
    let all: Vec<Value> = serde_json::from_str(&std::fs::read_to_string(path).expect("run `make conformance-vectors` first")).unwrap();
    assert!(all.len() >= 200, "need at least 200 scenarios");
    let (mut steps, mut mismatches) = (0, 0);
    for sc in &all {
        let mut c = Core::new(params(&sc["params"], &sc["publishers"], &sc["relief"]), sc["launcher"].as_str().unwrap()).unwrap();
        for (i, st) in sc["steps"].as_array().unwrap().iter().enumerate() {
            let a = st["args"].as_array().unwrap();
            let s = |k: usize| a[k].as_str().unwrap().to_string();
            let n = |k: usize| a[k].as_u64().unwrap();
            let now = st["now"].as_u64().unwrap();
            // an origin before 1970 (a negative number in the vectors) can never be valid: treated as a rejection, as Python rejects it
            let ok = match st["op"].as_str().unwrap() {
                "transfer" => c.ft_transfer(&s(0), &s(1), n(2) as u128).is_ok(),
                "tap" => c.tap(&s(0), "pool").is_ok(),
                "attest" => a[3].as_i64().unwrap() >= 0 && c.attest(&s(0), &s(1), n(2) as u32, n(3), now).is_ok(),
                "claim" => a[3].as_i64().unwrap() >= 0 && c.submit_claim(&s(0), &s(1), n(2) as u32, n(3), now).is_ok(),
                other => panic!("unknown op {other}"),
            };
            c.check_invariants();
            steps += 1;
            if ok != st["ok"].as_bool().unwrap() || snapshot(&c) != st["snap"] {
                mismatches += 1;
                if mismatches <= 3 { eprintln!("MISMATCH seed {} step {} op {} ok(rust)={} ok(py)={}", sc["seed"], i, st["op"], ok, st["ok"]); }
            }
        }
    }
    eprintln!("conformance: {} scenarios, {} steps, {} mismatches", all.len(), steps, mismatches);
    assert_eq!(mismatches, 0);
}

#[test]
fn golden_vector_one_from_rules_md() {
    // GV-1 straight from RULES.md, independent of the Python reference: each event is confirmed by 3 bots at its own origin time.
    let pubs: Vec<String> = (1..=5).map(|i| format!("bot{i}")).collect();
    let p = Params { s0: 1_000_000_000_000, min_mag_x10: 60, base_ppm: 5000, max_event_ppm: 15000, cooldown_s: 86400, week_cap_ppm: 15000, month_cap_ppm: 50000,
        min_age_s: 0, max_age_s: 5_184_000, max_open: 64, max_claims: 32, claim_wait_s: 43200, threshold: 3, tap_amount: 0, publishers: pubs.clone(),
        relief: (1..=5).map(|i| format!("r{i}")).collect() };
    let t0 = 20000 * DAY;
    let mut c = Core::new(p, "ada").unwrap();
    let run = |c: &mut Core, id: &str, mag: u32, origin: u64| {
        let mut out = None;
        for b in &pubs[..3] { out = c.attest(b, id, mag, origin, origin).unwrap(); }
        out.unwrap()
    };
    assert_eq!(run(&mut c, "E1", 60, t0), (5_000_000_000, 5_000_000_000, false));
    assert_eq!(run(&mut c, "E2", 70, t0 + 48 * 3600), (10_050_000_000, 10_050_000_000, false));
    let (m, raw, clipped) = run(&mut c, "E3", 60, t0 + 60 * 3600);
    assert_eq!((m, raw, clipped, c.supply), (175_750_000, 2_537_625_000, true, 1_015_225_750_000));
    assert_eq!(c.tok["r2"], 3_045_150_000);
    c.check_invariants();
}
